@pytest.mark.parametrize("family", [PolicyPackageInlineFormSet, PolicyNativeInlineFormSet], ids=["package", "native"]) @pytest.mark.parametrize( "identity", ["missing", "malformed", "nonexistent", "foreign", "filtered", "misbound", "valid"] ) @pytest.mark.parametrize("deleted", [False, True]) def test_reclean_uuid_existing_identity_and_unsaved_default_are_distinct(family, identity, deleted): author = Author.objects.create(first_name="Ursula", last_name="Le Guin") row = UUIDFragmentRow.objects.create(author=author, text="original") other_author = Author.objects.create(first_name="Other", last_name="Author") foreign = UUIDFragmentRow.objects.create(author=other_author, text="foreign") other = UUIDFragmentRow.objects.create(author=author, text="other authorized") prefix = f"rows-{author.pk}-0" payload = { "first_name": "Ursula", "last_name": "Le Guin", f"{prefix}-TOTAL_FORMS": "2", f"{prefix}-INITIAL_FORMS": "1", f"{prefix}-0-id": { "missing": "", "malformed": "bad-pk", "nonexistent": str(uuid.uuid4()), "foreign": str(foreign.pk), "filtered": str(row.pk), "misbound": str(row.pk), "valid": str(row.pk), }[identity], f"{prefix}-0-text": "edited", f"{prefix}-1-id": "", f"{prefix}-1-text": "new default UUID", } if deleted: payload[f"{prefix}-0-DELETE"] = "on" queryset = UUIDFragmentRow.objects.filter(author=author).exclude(pk=row.pk) if identity == "filtered" else None tree = uuid_runtime(family, author, payload, queryset=queryset) if identity == "misbound": tree.x_formsets[0].forms[0].form.instance = other extra = tree.x_formsets[0].forms[1].form.instance assert isinstance(extra.pk, uuid.UUID) assert extra._state.adding is True assert tree.all_valid() is (identity == "valid") for _ in range(2): tree.x_formsets[0].instance.full_clean() for _ in range(2): assert tree.all_valid() is (identity == "valid") if identity != "valid": errors = tree.x_formsets[0].instance.non_form_errors().as_data() > assert [(e.code, e.messages) for e in errors] == [("cv_invalid_row", ["Invalid row."])] E AssertionError: assert [] == [('cv_invalid...valid row.'])] E E Right contains one more item: ('cv_invalid_row', ['Invalid row.']) E Use -v to get more diff
